import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int initial = sc.nextInt();
        int n = sc.nextInt();
        Product product = new Product();
        product.stock = initial;
        for(int i = 0; i < n; i++) {
            String op = sc.next();
            int qty = sc.nextInt();
            if(op.equals("B")) {
                product.buy(qty);
            } else {
                product.sell(qty);
            }
        }
        System.out.println(product.getStock());
    }
}

class Product {
    int stock;

    void buy(int qty) {
        stock = stock + qty;
    }

    void sell(int qty) {
        if(qty <= stock) {
            stock = stock - qty;
        }
    }

    int getStock() {
        return stock;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int initial = sc.nextInt();
        int n = sc.nextInt();
        Phone phone = new Phone();
        phone.setBattery(initial);
        for(int i = 0; i < n; i++) {
            String op = sc.next();
            int q = sc.nextInt();
            if(op.equals("D")) {
                phone.drain(q);
            } else {
                phone.charge(q);
            }
        }
        phone.show();
    }
}

class Phone {
    private int battery;

    void setBattery(int b) {
        battery = b;
    }

    void drain(int percent) {
        battery = battery - percent;
        if(battery < 0) {
            battery = 0;
        }
    }

    void charge(int percent) {
        battery = battery + percent;
        if(battery > 100) {
            battery = 100;
        }
    }

    void show() {
        System.out.println("Battery: " + battery + "%");
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Song song = new Song();
        song.setTitle(sc.next());
        int n = sc.nextInt();
        for(int i = 0; i < n; i++) {
            song.play();
        }
        System.out.println(song.getTitle() + " played " + song.getPlays() + " times");
    }
}

class Song {
    private String title;
    private int plays;

    void setTitle(String t) {
        title = t;
    }

    void play() {
        plays++;
    }

    String getTitle() {
        return title;
    }

    int getPlays() {
        return plays;
    }
}

import java.util.Scanner;

public class Main {
