        Scanner sc = new Scanner(System.in);
        Order order = new Order();
        order.item = sc.next();
        order.qty = sc.nextInt();
        order.price = sc.nextDouble();
        order.printTicket();
    }
}

class Order {
    String item;
    int qty;
    double price;

    double total() {
        return qty * price;
    }

    void printTicket() {
        System.out.println("Item: " + item + " x " + qty);
        System.out.printf("Total: %.2f%n", total());
    }
}
